utxo = {'a:0': 50, 'b:1': 30}
def apply(ins, outs, txid):
    for i in ins:
        del utxo[i]
    for n, v in enumerate(outs):
        utxo[txid + ':' + str(n)] = v
apply(['a:0'], [20, 29], 'c')
apply(['c:0', 'b:1'], [45], 'd')
print(sorted(utxo), sum(utxo.values()))

used = {0, 3, 12, 30}
gap, run, found = 10, 0, []
for i in range(40):
    if i in used:
        found.append(i)
        run = 0
    else:
        run += 1
        if run == gap:
            break
print(sum(found))
